 async function updateCoverage(force=false){const key=coverageSignature();if(coverageKey.startsWith(docId+':'))paintCoverage(lastCoverage);if(coverageBusy||!docId||!force&&key===coverageKey)return;const identity=docId;let received=false;coverageBusy=true;try{const value=await api('/api/coverage?summary=true');received=true;if(identity!==docId)return;lastCoverage=value;paintCoverage(value);coverageKey=key}catch{}finally{coverageBusy=false;if(docId&&(received||identity!==docId)&&coverageSignature()!==coverageKey)setTimeout(()=>updateCoverage(),0)}}


 function installIcons(){$('connect').before(ReaderUI.hoverButton());for(const [id,name,label] of [['library-toggle','folder','打开材料文件树'],['connect','plug','连接 Codex'],['settings','settings','设置问法和阅读配色'],['statistics','samples','查看学习统计'],['library-import','upload','导入材料'],['choose-import','folder','选择材料文件'],['start-import','upload','导入所选材料']])ReaderUI.decorate($(id),name,label);for(const b of document.querySelectorAll('[data-panel]'))ReaderUI.decorate(b,{directory:'directory',original:'file',translation:'translation',interaction:'message',study:'book',explanation:'book'}[b.dataset.panel],b.title);for(const [id,name,label] of [['theme','theme','切换明暗主题'],['original-full','external','打开完整原件'],['page-prev','back','上一页'],['page-next','forward','下一页'],['zoom-out','minus','缩小'],['zoom-in','plus','放大'],['fit-highlight','fit','按高亮区域适配宽度'],['scope','all','切换当前范围和完整译文'],['history-back','back','返回上一阅读位置'],['history-forward','forward','前进到下一阅读位置'],['next-passage','forward','目录下一章'],['mark-read','check','标记当前页已读'],['graph','graph','查看当前段落关系图']])ReaderUI.decorate($(id),name,label);document.querySelectorAll('[data-close]').forEach(b=>ReaderUI.decorate(b,'close','关闭'))}
 async function start(){try{ReaderBoot?.stage('正在准备阅读窗口');installIcons();contentUI=ReaderWorkspaceUI.create({material:()=>material,state:()=>state,current,rich,terms:linkTerms,select:selectSentence,focus:setFocus,post,refresh,renderSources:()=>{renderOutline();renderTranslation();renderOriginal();renderInteraction()},status,mobile:()=>mobile,mobilePanel:()=>mobilePanel,panel:selectPanel,visibility:()=>visible,waitForFocus:()=>{focusSeq++;return focusQueue.catch(()=>{})},pausePolling,resumePolling:schedulePoll,flushDraft,capture:captureView,authoredPage,readControls:updateReadPageButton,inlineQuestions:attachInlineQuestions,sourceFlow:root=>sourceFlow?.annotate(root),chinese:makeChinese,fit:()=>{if(autoFit&&material&&state)fitCurrent()},openDocument:loadDocument,reloadLibrary:loadLibrary});projectFilesUI=ReaderProjectFiles.create({api,watch:(url,signal)=>fetch(url,{signal,headers:{'X-Reader-Pin':pin||'','X-Reader-Material':docId}}),file:async url=>{if(!pin)return url;const response=await fetch(url,{headers:{'X-Reader-Pin':pin,'X-Reader-Material':docId}});if(!response.ok)throw Error('读取文件失败');return URL.createObjectURL(await response.blob())},material:()=>material,rich,status,drawOutline,label:()=>contentUI.directoryMode()==='learning'?'讲解目录':'原文目录',mode:()=>outlineMode,setMode:(mode,paint=true)=>{outlineMode=mode;localStorage.setItem('reader-outline-progress',mode);if(paint)renderOutline()},showOriginal:()=>{const shown=contentUI.snapshot().columns.flat().includes('original');if(mobile?mobilePanel!=='original':!shown)selectPanel('original')},showDirectory:()=>{if(mobile?mobilePanel!=='directory':!visible.directory)selectPanel('directory')}});sourceFlow=ReaderSourceFlow.create({main:()=>projectFilesUI.showMain(),material:()=>material,content:()=>contentUI,scope:()=>scope,focus:()=>state?.focus,fileURL,draw:drawPage,paintRefs:refs=>{const info=material?.pages[currentPage],root=$('pdf-highlights');root.replaceChildren();if(info){const layer=ReaderUI.highlightLayer(refs.filter(r=>r.page_id===currentPage&&r.bbox),info.width,info.height);if(layer)root.append(layer)}},refs:selectedRefs,rich,attachInputs:attachInlineQuestions,questions:()=>state?.rounds.flatMap(r=>r.questions)||[],groupInput:(input,ids,text)=>{const b=inputBlock(input);if(!b.value.trim()){b.source_refs=ids;b.source_excerpt=text}}});ReaderMarkdown.installSelection($('translation'));ReaderBoot?.stage('正在连接阅读器');const session=await(await fetch('/api/session')).json();pin=session.pin;base=session.api_base;remoteSession=session;ReaderRemoteUI.init(session,{post,api,current:()=>docId});docId=new URL(location.href).searchParams.get('material')||session.material_id;ReaderBoot?.stage('正在读取当前材料');const requested=docId,prepared=requested?Promise.all([api('/api/material'),api('/api/progress')]):null;prepared?.catch(()=>{});await loadSettings();let chosen=requested?{id:requested}:null;if(!chosen){await loadLibrary();chosen=libraryEntries[0]}else loadLibrary().catch(e=>status('材料树暂未读取：'+e.message));if(chosen){await loadDocument(chosen.id,chosen.id===requested?prepared:null);const anchor=new URL(location.href).searchParams.get('source_anchor'),section=new URL(location.href).searchParams.get('section');if(anchor&&material.passages.some(p=>p.id===anchor)){if(section&&state.learning?.nodes.some(n=>n.id===section))await contentUI.selectLearning(section);contentUI.beforeLocate(anchor);await setFocus(anchor);await sourceFlow?.link({passage_id:anchor},'statistics',{toggle:false})}status('可以开始阅读；问题会自动保存，在 Codex 对话中触发回答')}else emptyLibrary();schedulePoll();ReaderBoot?.ready()}catch(error){status('打开阅读器时遇到问题：'+error.message);ReaderBoot?.error(error.message)}}
 start();
